sql:
SELECT Name
FROM Genre
ORDER BY Name ASC;

SELECT COUNT(*) AS brazil_customer_count
FROM Customer
WHERE Country = 'Brazil';

SELECT FirstName, LastName
FROM Employee
WHERE Title LIKE '%Sales Support Agent%';

SELECT Title
FROM Album
WHERE Title ILIKE '%Greatest%';

SELECT Name
FROM Track
WHERE Milliseconds > 1200000;

SELECT COUNT(*) AS invoice_count
FROM Invoice
WHERE EXTRACT(year FROM InvoiceDate) = 2023;

SELECT
    ROUND(100.0 * SUM(CASE WHEN Milliseconds > 300000 THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_longer_than_5_min
FROM Track;

SELECT iso3, name
FROM countries
WHERE region = 'South Asia';

SELECT capital_city
FROM countries
WHERE iso3 = 'JPN' OR name = 'Japan';

SELECT COUNT(*) AS low_income_countries
FROM countries
WHERE income_group = 'Low income';

SELECT population
FROM country_stats
WHERE iso3 = 'IND' AND year = 2023;

SELECT COUNT(*) AS gentoo_count
FROM penguins
WHERE species = 'Gentoo';

SELECT COUNT(*) AS unknown_sex_count
FROM penguins
WHERE sex IS NULL;

SELECT species, COUNT(*) AS count
FROM penguins
GROUP BY species;
